/**
 * Emit public/_redirects from the single redirect maps used by Node + CF.
 * Run before `astro build` so dist/ receives the same rules.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { PATH_REDIRECTS } from '../src/config/path-redirects.mjs';
import { CHECKOUT_PATH_REDIRECTS } from '../src/config/checkout-redirects.mjs';

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const outFile = path.join(root, 'public', '_redirects');

const lines = [
  '# Generated by scripts/write-redirects.mjs — do not edit by hand.',
  '# Source maps: scripts/redirects.mjs (301) + src/config/checkout-redirects.mjs (302).',
  '',
  '# Canonical host: https://warthunder-cheats.com only',
  'https://www.warthunder-cheats.com/* https://warthunder-cheats.com/:splat 301',
  'http://warthunder-cheats.com/* https://warthunder-cheats.com/:splat 301',
  'http://www.warthunder-cheats.com/* https://warthunder-cheats.com/:splat 301',
  '',
  '# Path redirects (301 → final URL)',
];

for (const [from, to] of PATH_REDIRECTS) {
  lines.push(`${from} ${to} 301`);
}

lines.push('', '# Checkout hops (302 → Zadeyo; noindex via redirect, no HTML bridge)');
for (const [from, to] of CHECKOUT_PATH_REDIRECTS) {
  lines.push(`${from} ${to} 302`);
}

lines.push('');
fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, lines.join('\n'), 'utf8');
console.log(`Wrote ${outFile} (${PATH_REDIRECTS.size} path + ${CHECKOUT_PATH_REDIRECTS.size} checkout rules)`);
